Convert SQL to PySpark:
```sql
select assay_kind, pct_soil
from (
    select assay_kind, round((100 * sum(case when specimen_kind = 'soil' then 1 else 0 end)) / count(*), 1) pct_soil
    from instruments
    group by assay_kind
) agg
where pct_soil < 74;
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by panel_region order by share_pct, id) as rnk
    from ad_spots
    where share_pct < 41
) as t
where rnk <= 3;
```

Convert SQL to PySpark:
```sql
select activated_month, pct_postpaid, total_signal_dbm
from (
    select month(activated_date) as activated_month, round((100 * sum(case when plan_tier = 'postpaid' then 1 else 0 end)) / count(*), 1) as pct_postpaid, sum(signal_dbm) as total_signal_dbm
    from cell_towers
    group by month(activated_date)
) as sub
where pct_postpaid < 56;
```

Convert SQL to PySpark:
```sql
select id, hotel_id, checkout_day
from (
    select *, dense_rank() over (partition by hotel_id order by checkout_day desc) rn
    from housekeeping_tasks
) r
where rn <= 2;
```

Convert SQL to PySpark:
```sql
select *
from (
    select case when lane_throughput >= 261 then 'high' when lane_throughput >= 84 then 'mid' else 'low' end as lane_throughput_bucket, sum(lane_throughput) as total_lane_throughput, min(lane_throughput) as min_lane_throughput
    from concession_sales
    group by case when lane_throughput >= 261 then 'high' when lane_throughput >= 84 then 'mid' else 'low' end
) as agg
where total_lane_throughput >= 1130;
```

Convert SQL to PySpark:
```sql
select id, vessel_id, built_on
from (
    select *, row_number() over (partition by vessel_id order by built_on desc, id) rnk
    from crew_members
) r
where rnk <= 5;
```

Convert SQL to PySpark:
```sql
select announced_year, pct_floor, max_stage_width_m
from (
    select year(announced_date) as announced_year, round((100 * sum(case when tier_section = 'floor' then 1 else 0 end)) / count(*), 1) as pct_floor, max(stage_width_m) as max_stage_width_m
    from concerts
    group by year(announced_date)
) as x
where max_stage_width_m >= 22;
```
